using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
using UnityEditor;
public static class MakongRouteSetup {
 public static readonly string[] Keys={"key.red","key.green","key.master"};
 static DungeonMapEntity Door(DungeonEntitySettings e,int x,int y){var d=e.objects.SingleOrDefault(o=>o.kind==DungeonEntityKind.Door&&o.cell==new Vector2Int(x,y));if(d==null)throw new Exception("Puerta no encontrada "+x+","+y);return d;}
 public static string Apply(){var map=DungeonMapSettings.Current;var entities=map.entities;var regions=map.regions!=null?map.regions:DungeonRegionSettings.Current;
  var first=Door(entities,16,42);var red=Door(entities,3,46);var green=entities.objects.Single(o=>o.kind==DungeonEntityKind.Door&&(o.cell==new Vector2Int(20,48)||o.cell==new Vector2Int(20,47)));var master=Door(entities,11,46);
  var inventory=Resources.Load<CombatInventorySettings>("Combat/CombatInventorySettings");var items=inventory.items.ToList();string[] names={"Llave Roja","Llave Verde","Llave Maestra"};for(int n=0;n<3;n++)if(!items.Any(i=>i.id==Keys[n]))items.Add(new CombatItemDefinition(names[n],0,0){id=Keys[n],keyItem=true});inventory.items=items.ToArray();
  first.heading=1;first.doorKind=DungeonDoorKind.Normal;first.doorInitiallyOpen=true;red.doorKind=green.doorKind=master.doorKind=DungeonDoorKind.Locked;red.requiredKeyId=Keys[0];green.requiredKeyId=Keys[1];master.requiredKeyId=Keys[2];green.cell=new Vector2Int(20,47);red.heading=green.heading=master.heading=0;
  var placements=regions.placedEnemies.ToList();string[] species={"BigTapaku","GranMakuba","GranMakuba"};Vector2Int[] guardCells={new Vector2Int(19,44),new Vector2Int(3,50),new Vector2Int(20,50)};Vector2Int[] chestCells={new Vector2Int(20,41),new Vector2Int(1,51),new Vector2Int(19,51)};
  for(int n=0;n<3;n++){if(EnemyCharacterCatalog.Current.FindId(species[n])==null)throw new Exception("Especie no registrada "+species[n]);var guardId="makong.key.guard."+n;var guard=placements.Find(p=>p.id==guardId);if(guard==null){if(placements.Any(p=>p.cell==guardCells[n])||entities.objects.Any(e=>e.cell==guardCells[n]))throw new Exception("Casilla ocupada");guard=new PlacedEnemyDefinition{id=guardId};placements.Add(guard);}guard.speciesId=species[n];guard.cell=guardCells[n];guard.fixedLevel=7+n;guard.randomLevel=false;guard.category=PlacedEnemyCategory.Elite;guard.unique=true;guard.respawn=false;guard.countsTowardLimit=false;guard.holdPosition=true;guard.guaranteedDrops=new[]{new InventoryItemRecord{itemId=inventory.items[n==2?1:0].id,quantity=1}};
   var chest=entities.objects.Find(e=>e.kind==DungeonEntityKind.Chest&&e.cell==chestCells[n]);if(chest!=null&&!string.IsNullOrEmpty(chest.contentId)&&chest.contentId!=Keys[n])throw new Exception("No se sobrescribe contenido existente");if(chest==null){chest=new DungeonMapEntity{id="makong.key.chest."+n,kind=DungeonEntityKind.Chest,cell=chestCells[n]};entities.objects.Add(chest);}chest.chestKind=DungeonChestKind.KeyItem;chest.contentId=Keys[n];chest.quantity=1;chest.displayName="Cofre — "+names[n];chest.guardPlacementId=guardId;
  }regions.placedEnemies=placements.ToArray();var levels=PlayerLevelSettings.Current;levels.healMaximumFraction=1;levels.healFlatHP=0;
  string report=ValidateRoute(map);foreach(var asset in new UnityEngine.Object[]{entities,regions,inventory,levels})EditorUtility.SetDirty(asset);AssetDatabase.SaveAssets();return report;
 }
 public static HashSet<Vector2Int> Reach(DungeonMapSettings map,Vector2Int start,HashSet<string> keys){var found=new HashSet<Vector2Int>{start};var q=new Queue<Vector2Int>();q.Enqueue(start);var dirs=new[]{Vector2Int.up,Vector2Int.right,Vector2Int.down,Vector2Int.left};while(q.Count>0){var at=q.Dequeue();foreach(var d in dirs){var next=at+d;if(!map.IsFloor(next)||map.entities.objects.Any(e=>(e.kind==DungeonEntityKind.Chest||e.kind==DungeonEntityKind.NPC||e.kind==DungeonEntityKind.Savepoint)&&e.cell==next))continue;bool blocked=map.entities.objects.Any(e=>e.kind==DungeonEntityKind.Door&&!e.doorInitiallyOpen&&e.doorKind==DungeonDoorKind.Locked&&!keys.Contains(e.requiredKeyId)&&((e.cell==at&&e.cell+dirs[e.heading]==next)||(e.cell==next&&e.cell+dirs[e.heading]==at)));if(!blocked&&found.Add(next))q.Enqueue(next);}}return found;}
 public static string ValidateRoute(DungeonMapSettings map){var start=RefugeSettings.Current.startCell;var keys=new HashSet<string>();var targets=new[]{new Vector2Int(20,41),new Vector2Int(1,51),new Vector2Int(19,51)};var report=new List<string>();for(int stage=0;stage<4;stage++){var cells=Reach(map,start,keys);bool boss=cells.Contains(new Vector2Int(12,53));if(boss!=(stage==3))throw new Exception("Acceso incorrecto a Makong fase "+stage);for(int k=0;k<3;k++){bool adjacent=new[]{Vector2Int.up,Vector2Int.right,Vector2Int.down,Vector2Int.left}.Any(d=>cells.Contains(targets[k]+d));if(adjacent!=(k<=stage))throw new Exception("Secuencia de llave inválida "+k+" fase "+stage);}report.Add("Fase "+stage+": "+cells.Count+" casillas; Makong "+boss);if(stage<3)keys.Add(Keys[stage]);}
  var all=Reach(map,start,keys);foreach(var e in map.entities.objects.Where(e=>e.id.StartsWith("makong.prep.")))if(!new[]{Vector2Int.up,Vector2Int.right,Vector2Int.down,Vector2Int.left}.Any(d=>all.Contains(e.cell+d)))throw new Exception("Equipo inaccesible "+e.id);return string.Join("\n",report.ToArray());
 }
}
